.darma-loader-darma-b14-syringe-plunger { --accent: var(--loader-color, #0d9488); --accent-2: var(--loader-secondary-color, #5eead4); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .42); position: relative; }
.darma-loader-darma-b14-syringe-plunger::before { content: ''; position: absolute; left: 12%; top: 16%; width: 62%; height: 68%; border-radius: 3px; background: rgba(255, 255, 255, .45); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 18%, var(--accent-2)); }
.darma-loader-darma-b14-syringe-plunger::after { content: ''; position: absolute; left: 0; top: 44%; width: 13%; height: 8%; border-radius: 999px 0 0 999px; background: #94a3b8; }
.darma-loader-darma-b14-syringe-plunger span { position: absolute; left: 13%; top: 20%; height: 60%; border-radius: 2px; background: linear-gradient(90deg, var(--accent), var(--accent-2)); animation: darma-loader-darma-b14-syringe-plunger-inject calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b14-syringe-plunger .darma-loader-darma-b14-syringe-plunger__plunger { position: absolute; top: 30%; width: 30%; height: 40%; border-radius: 2px; background: linear-gradient(#f1f5f9, #94a3b8); animation: darma-loader-darma-b14-syringe-plunger-push calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b14-syringe-plunger .darma-loader-darma-b14-syringe-plunger__plunger::after { content: ''; position: absolute; left: 96%; top: -60%; width: 14%; height: 220%; border-radius: 2px; background: #cbd5e1; }
@keyframes darma-loader-darma-b14-syringe-plunger-inject { 0%, 12% { width: 60%; } 56%, 70% { width: 5%; } 94%, 100% { width: 60%; } }
@keyframes darma-loader-darma-b14-syringe-plunger-push { 0%, 12% { right: 2%; } 56%, 70% { right: 57%; } 94%, 100% { right: 2%; } }

